/// Raven `Pickup_Health`.
///
/// Source: `oracle/oracle/codemp/game/g_items.c:2237-2266`
pub fn Pickup_Health(
    ent: *mut gentity_t,
    other: *mut gentity_t,
) -> c_int {
    // Raven local `#define`s (`g_items.c:23-27`).
    const RESPAWN_HEALTH: f32 = 30.0;
    const RESPAWN_MEGAHEALTH: c_int = 120;

    unsafe {
        let item = (*ent).item;

        // small and mega healths will go over the max
        let max = if (*item).quantity != 5 && (*item).quantity != 100 {
            (*(*other).client).ps.stats[statIndex_t::STAT_MAX_HEALTH as usize]
        } else {
            (*(*other).client).ps.stats[statIndex_t::STAT_MAX_HEALTH as usize] * 2
        };

        let quantity = if (*ent).count != 0 {
            (*ent).count
        } else {
            (*item).quantity
        };

        (*other).health += quantity;

        if (*other).health > max {
            (*other).health = max;
        }
        (*(*other).client).ps.stats[statIndex_t::STAT_HEALTH as usize] = (*other).health;

        if (*item).quantity == 100 {
            // mega health respawns slow
            return RESPAWN_MEGAHEALTH;
        }

        adjustRespawnTime(RESPAWN_HEALTH, (*item).giType as c_int, (*item).giTag)
    }
}

/// Raven `Pickup_Armor`.
///
/// Source: `oracle/oracle/codemp/game/g_items.c:2270-2279`
pub fn Pickup_Armor(
    ent: *mut gentity_t,
    other: *mut gentity_t,
) -> c_int {
    // Raven local `#define` (`g_items.c:21`).
    const RESPAWN_ARMOR: f32 = 20.0;

    unsafe {
        let item = (*ent).item;
        let cl = (*other).client;

        (*cl).ps.stats[statIndex_t::STAT_ARMOR as usize] += (*item).quantity;
        let cap = (*cl).ps.stats[statIndex_t::STAT_MAX_HEALTH as usize] * (*item).giTag;
        if (*cl).ps.stats[statIndex_t::STAT_ARMOR as usize] > cap {
            (*cl).ps.stats[statIndex_t::STAT_ARMOR as usize] = cap;
        }

        adjustRespawnTime(RESPAWN_ARMOR, (*item).giType as c_int, (*item).giTag)
    }
}

